def make_F(n: int, m: int, seed: int = 12345):
    F = np.empty((n, m))
    s = seed
    for i in range(n):
        for j in range(m):
            s = (s * 1103515245 + 12345) % 2147483648
            F[i, j] = float(s % 20001 - 10000) * 0.000123 * float(j + 1)
    return F

def make_y(n: int):
    return np.array([(i * 7 % 5) % 2 for i in range(n)])

nan = float("nan")
inf = float("inf")

def close(got, exp: List[float], tol: float = 1e-12) -> bool:
    if len(got) != len(exp):
        print("size mismatch", len(got), len(exp))
        return False
    ok = True
    for i in range(len(exp)):
        a = got[i]
        b = exp[i]
        if a != a and b != b:
            continue
        if (a != a) != (b != b) or abs(a - b) > tol + tol * abs(b):
            print("mismatch at", i, a, b)
            ok = False
    return ok

def vals(s: pd.Series) -> List[float]:
    return [float(x) for x in s.to_numpy()]

def fvals(d: pd.DataFrame) -> List[float]:
    out = List[float]()
    a = d.to_numpy()
    for i in range(a.shape[0]):
        for j in range(a.shape[1]):
            out.append(float(a[i, j]))
    return out

def strs(s: pd.Series) -> List[str]:
    return [str(x) for x in s.tolist()]

def sdf(d: pd.DataFrame) -> List[str]:
    out = List[str]()
    for j in range(len(d.columns)):
        for x in d.iloc[:, j].tolist():
            out.append(str(x))
    return out

